import React, { useEffect, useRef, useState } from 'react';
import { Button, Drawer, Form, Input, Empty, Popconfirm, Select, Space, Spin, Table, message } from 'antd';
import { PlusOutlined, ReloadOutlined } from '@ant-design/icons';
import { VditorEditor } from '@1flowbase/rich-text';

const PATH = '/api/runtime/models/daily_reports';
const today = () => new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());

export default function DailyReports({ ctx }) {
  const available = ctx.ui.sizing?.available;
  const compact = !!available?.width && available.width < 900;
  const [compactHeight, setCompactHeight] = useState(480);
  useEffect(() => {
    if (!compact) return;
    const host = ctx.root.host;
    const owner = host.closest('[data-flowbase-frontstage-scroll-owner]');
    const viewportBottom = host.ownerDocument.documentElement.clientHeight;
    const bottom = owner ? Math.min(owner.getBoundingClientRect().bottom, viewportBottom) : viewportBottom;
    const height = Math.max(240, Math.floor(bottom - Math.max(0, host.getBoundingClientRect().top) - 16));
    setCompactHeight(height);
    ctx.ui.sizing?.reportIntrinsicSize({ height });
  }, [compact, available?.width, available?.height]);
  const [search, setSearch] = useState('');
  const [keyword, setKeyword] = useState('');
  const [sort, setSort] = useState('created_at:desc');
  const listRef = useRef(null);
  const requestRef = useRef(0);
  const loadingRef = useRef(false);
  const [loadError, setLoadError] = useState(false);
  const [rows, setRows] = useState([]);
  const [selectedId, setSelectedId] = useState('');
  const viewRequestRef = useRef(0);

  async function selectReport(record, openDrawer = false) {
    setSelectedId(record.id);
    const result = await ctx.outputs.publish({ id: record.id, view_request: openDrawer ? ++viewRequestRef.current : 0 });
    if (!result.ok && !result.stale) message.error('日报详情联动失败，请刷新后重试');
  }
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [users, setUsers] = useState({});
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editing, setEditing] = useState(null);
  const [content, setContent] = useState('');
  const contentRef = useRef('');
  const [contentError, setContentError] = useState('');
  const [form] = Form.useForm();

  async function load(nextPage = page, append = false) {
    if (append && loadingRef.current) return;
    const request = ++requestRef.current;
    loadingRef.current = true;
    setLoading(true);
    setLoadError(false);
    if (!append) { setRows([]); setTotal(0); }
    try {
      const query = { page: nextPage, page_size: 20, sort };
      if (keyword) query.filter = JSON.stringify({ title: { $includes: keyword } });
      const reports = await ctx.api.get(PATH + '/list', { query });
      if (request !== requestRef.current) return;
      setRows(current => append ? [...current, ...(reports.items || [])] : (reports.items || []));
      setTotal(reports.total || 0);
      setPage(nextPage);
    } catch (error) {
      if (request !== requestRef.current) return;
      setLoadError(true);
      message.error(error?.message || '读取日报失败');
    } finally {
      if (request === requestRef.current) {
        loadingRef.current = false;
        setLoading(false);
      }
    }
  }

  useEffect(() => {
    const timer = setTimeout(() => setKeyword(search.trim()), 300);
    return () => clearTimeout(timer);
  }, [search]);
  useEffect(() => {
    if (listRef.current) listRef.current.scrollTop = 0;
    load(1);
    return () => { ++requestRef.current; loadingRef.current = false; };
  }, [keyword, sort, compact]);
  useEffect(() => {
    if (compact) return;
    let active = true;
    ctx.api.get('/api/runtime/models/users/list', { query: { page: 1, page_size: 100 } })
      .then(result => {
        if (active) setUsers(Object.fromEntries((result.items || []).map(user => [user.id, user.nickname || user.name || user.account || user.id])));
      })
      .catch(() => { if (active) message.warning('创建者名称加载失败，暂显示用户 ID'); });
    return () => { active = false; };
  }, [compact]);
  useEffect(() => {
    const list = listRef.current;
    if (compact && list && !loading && !loadError && rows.length > 0 && rows.length < total && list.scrollHeight <= list.clientHeight + 48) {
      load(page + 1, true);
    }
  }, [compact, loading, loadError, rows.length, total, page, available?.height]);
  useEffect(() => { if (editing) form.setFieldsValue(editing); }, [editing]);

  function openEditor(record) {
    const next = record || { title: '', summary: '', content: '', report_date: today() };
    contentRef.current = next.content || '';
    setContent(contentRef.current);
    setContentError('');
    setEditing(next);
  }

  async function save() {
    try {
      const values = await form.validateFields();
      if (!contentRef.current.trim()) { setContentError('请填写正文'); return; }
      setSaving(true);
      const body = { title: values.title.trim(), summary: values.summary.trim(), content: contentRef.current.trim(), report_date: values.report_date };
      if (editing?.id) {
        await ctx.api.patch(PATH + '/update/{id}', { path: { id: editing.id }, body });
      } else {
        await ctx.api.post(PATH + '/create', { body });
      }
      message.success('日报已保存');
      setEditing(null);
      await load(editing?.id ? page : 1);
    } catch (error) {
      if (!error?.errorFields) message.error(error?.message || '保存日报失败');
    } finally {
      setSaving(false);
    }
  }

  async function remove(record) {
    try {
      await ctx.api.delete(PATH + '/delete/{id}', { path: { id: record.id } });
      message.success('日报已删除');
      if (selectedId === record.id) {
        setSelectedId('');
        await ctx.outputs.publish({ id: '', view_request: 0 });
      }
      await load(page);
    } catch (error) {
      message.error(error?.message || '删除日报失败');
    }
  }

  const columns = [
    { title: '标题', dataIndex: 'title', key: 'title', width: 260, ellipsis: true, render: (value, record) => <Button type="link" style={{ padding: 0 }} onClick={event => { event.stopPropagation(); selectReport(record); }}>{value}</Button> },
    { title: '摘要', dataIndex: 'summary', key: 'summary', ellipsis: true },
    { title: '创建者', dataIndex: 'created_by', key: 'created_by', width: 150, render: value => users[value] || value || '—' },
    { title: '创建时间', dataIndex: 'created_at', key: 'created_at', width: 190, render: value => value ? new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' }) : '—' },
    { title: '操作', key: 'actions', width: 150, render: (_, record) => <Space onClick={event => event.stopPropagation()}><Button type="link" onClick={event => { event.stopPropagation(); selectReport(record, true); }}>查看</Button><Popconfirm title="删除这篇日报？" onConfirm={() => remove(record)}><Button type="link" danger>删除</Button></Popconfirm></Space> }
  ];

  return <div aria-label="日报列表" data-view={compact ? 'list' : 'table'} style={{ padding: compact ? 16 : 24, minWidth: 0, boxSizing: 'border-box', height: compact ? compactHeight : undefined, display: 'flex', flexDirection: 'column', overflow: compact ? 'hidden' : undefined }}>
    <div style={{ display: 'flex', alignItems: 'center', flexWrap: compact ? 'nowrap' : 'wrap', gap: 8, marginBottom: 16, flexShrink: 0 }}>
      <Input.Search aria-label="搜索日报标题" placeholder="搜索标题" allowClear value={search} onChange={event => setSearch(event.target.value)} style={{ flex: '1 1 120px', minWidth: 0 }} />
      <Select aria-label="时间排序" value={sort} onChange={setSort} style={{ width: 124, flexShrink: 0 }} options={[{ value: 'created_at:desc', label: '时间倒序' }, { value: 'created_at:asc', label: '时间正序' }]} />
      {!compact && <Space><Button icon={<ReloadOutlined />} onClick={() => load(page)} loading={loading}>刷新</Button><Button type="primary" icon={<PlusOutlined />} onClick={() => openEditor(null)}>新增日报</Button></Space>}
    </div>
    {compact ? <div ref={listRef} aria-label="日报标题列表" onScroll={event => {
      const list = event.currentTarget;
      if (!loadError && rows.length < total && list.scrollHeight - list.scrollTop - list.clientHeight < 80) load(page + 1, true);
    }} style={{ flex: '1 1 0', minHeight: 0, overflowY: 'auto', overflowX: 'hidden', overscrollBehavior: 'contain' }}>
      {rows.map(record => <button key={record.id} type="button" aria-pressed={record.id === selectedId} onClick={() => selectReport(record)} style={{ display: 'block', width: '100%', padding: '14px 12px', border: 0, borderBottom: '1px solid var(--ant-color-border-secondary, #e8edea)', textAlign: 'left', cursor: 'pointer', font: 'inherit', color: 'var(--ant-color-text, #16211d)', background: record.id === selectedId ? 'var(--ant-color-primary-bg, #e6f7f2)' : 'transparent', overflowWrap: 'anywhere' }}>{record.title}</button>)}
      {loading && <div style={{ textAlign: 'center', padding: 16 }}><Spin size="small" /></div>}
      {!loading && loadError && <Button block onClick={() => load(rows.length ? page + 1 : 1, rows.length > 0)}>重新加载</Button>}
      {!loading && !loadError && !rows.length && <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={keyword ? '没有匹配的日报' : '暂无日报'} />}
    </div> : <Table rowKey="id" onRow={record => ({ onClick: () => selectReport(record), style: { cursor: 'pointer', background: record.id === selectedId ? 'var(--ant-color-primary-bg)' : undefined } })} columns={columns} dataSource={rows} loading={loading} pagination={{ current: page, pageSize: 20, total, showSizeChanger: false, onChange: nextPage => load(nextPage) }} />}
    <Drawer title={editing?.id ? '编辑日报' : '新增日报'} open={!!editing} defaultSize={780} minSize={480} maxSize={1200} resizable styles={{ wrapper: { minWidth: 'min(480px, 100vw)', maxWidth: '100vw' } }} destroyOnHidden onClose={() => setEditing(null)} extra={<Space><Button onClick={() => setEditing(null)}>取消</Button><Button type="primary" loading={saving} onClick={save}>保存</Button></Space>}>
      <Form form={form} layout="vertical">
        <div style={{ display: 'flex', flexWrap: 'wrap', columnGap: 16 }}>
          <Form.Item name="title" label="标题" style={{ flex: '3 1 320px', minWidth: 0 }} rules={[{ required: true, whitespace: true, message: '请填写标题' }]}><Input maxLength={200} /></Form.Item>
          <Form.Item name="report_date" label="报告日期" style={{ flex: '1 1 200px', minWidth: 0 }} rules={[{ required: true, message: '请选择报告日期' }]}><Input type="date" /></Form.Item>
        </div>
        <Form.Item name="summary" label="摘要" rules={[{ required: true, whitespace: true, message: '请填写摘要' }]}><Input.TextArea rows={4} maxLength={2000} showCount /></Form.Item>
        <Form.Item label="正文" required validateStatus={contentError ? 'error' : undefined} help={contentError || undefined}>
          <VditorEditor ariaLabel="日报正文编辑器" mode="wysiwyg" value={content} onChange={value => { contentRef.current = value; if (contentError && value.trim()) setContentError(''); }} height="auto" outline={false} />
        </Form.Item>
      </Form>
    </Drawer>
  </div>;
}

import React, { useEffect, useState } from 'react';
import { Alert, Button, Drawer, Empty, Spin, Typography } from 'antd';
import { XMarkdown } from '@ant-design/x-markdown';

const PATH = '/api/runtime/models/daily_reports';

function ReportContent({ report }) {
  return <article style={{ minWidth: 0, overflowWrap: 'anywhere' }}>
    <div style={{ display: 'flex', alignItems: 'baseline', flexWrap: 'wrap', gap: '8px 24px', marginBottom: 16 }}>
      <Typography.Title level={3} style={{ margin: 0, flex: '1 1 240px' }}>{report.title}</Typography.Title>
      <Typography.Text type="secondary">报告日期：{report.report_date}</Typography.Text>
    </div>
    <Typography.Paragraph type="secondary" style={{ whiteSpace: 'pre-wrap' }}>{report.summary}</Typography.Paragraph>
    <XMarkdown content={report.content || ''} className="x-markdown-light" escapeRawHtml openLinksInNewTab />
  </article>;
}

export default function DailyReportDetail({ ctx }) {
  const id = typeof ctx.inputs.id === 'string' ? ctx.inputs.id : '';
  const viewRequest = Number(ctx.inputs.view_request || 0);
  const [report, setReport] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [retry, setRetry] = useState(0);

  useEffect(() => {
    let active = true;
    setReport(null);
    setError('');
    if (!id) { setLoading(false); setDrawerOpen(false); return; }
    setLoading(true);
    ctx.api.get(PATH + '/get/{id}', { path: { id } })
      .then(record => { if (active) setReport(record); })
      .catch(error => { if (active) setError(error?.message || '读取日报失败'); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [id, retry]);

  useEffect(() => { setDrawerOpen(Boolean(id && viewRequest)); }, [id, viewRequest]);

  const body = loading ? <Spin tip="正在读取日报"><div style={{ minHeight: 160 }} /></Spin>
    : error ? <Alert type="error" showIcon message={error} action={<Button size="small" onClick={() => setRetry(value => value + 1)}>重试</Button>} />
    : report ? <ReportContent report={report} />
    : <Empty description="点击上方日报查看正文" image={Empty.PRESENTED_IMAGE_SIMPLE} />;

  return <section aria-label="日报详情" style={{ padding: 24, minWidth: 0 }}>
    {body}
    <Drawer title="查看日报" open={drawerOpen} defaultSize={780} minSize={480} maxSize={1200} resizable styles={{ wrapper: { minWidth: 'min(480px, 100vw)', maxWidth: '100vw' } }} destroyOnHidden onClose={() => setDrawerOpen(false)} extra={<Button onClick={() => setDrawerOpen(false)}>关闭</Button>}>
      {body}
    </Drawer>
  </section>;
}
